.sc-tw :root{
            --bg-void: oklch(0.12 0.02 250);
            --text-luma: oklch(0.98 0.01 250);
            --accent-photon: oklch(0.85 0.1 240);
            --surface-glass: rgba(255, 255, 255, 0.03);
            background-color: var(--bg-void);
            color: var(--text-luma);
            font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Helvetica Neue", sans-serif;
            scroll-behavior: smooth;
        }.sc-tw{
            overflow-x: hidden;
            background-image:
                radial-gradient(circle at 50% 0%, oklch(0.2 0.05 250 / 0.5), transparent 70%),
                linear-gradient(to right, rgba(255, 255, 255, 0.02) 1px, transparent 1px),
                linear-gradient(to bottom, rgba(255, 255, 255, 0.02) 1px, transparent 1px);
            background-size: 100% 100%, 4rem 4rem, 4rem 4rem;
            background-position: center top;
        }.sc-tw .kinetic-breach{
            mask-image: radial-gradient(circle at center, black 20%, transparent 80%);
            -webkit-mask-image: radial-gradient(circle at center, black 20%, transparent 80%);
            filter: saturate(1.2) brightness(0.8);
        }.sc-tw .glass-anodized{
            background: var(--surface-glass);
            border: 1px solid rgba(255, 255, 255, 0.08);
            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.15);
            backdrop-filter: blur(40px) saturate(150%);
            -webkit-backdrop-filter: blur(40px) saturate(150%);
        }.sc-tw .photon-glow{
            background: linear-gradient(180deg, rgba(255, 255, 255, 0.1) 0%, rgba(255, 255, 255, 0.03) 100%);
            border: 1px solid rgba(255, 255, 255, 0.2);
            transition: all 0.5s cubic-bezier(0.16, 1, 0.3, 1);
        }.sc-tw .photon-glow:hover{
            background: rgba(255, 255, 255, 0.15);
            border-color: var(--accent-photon);
            box-shadow: 0 0 30px oklch(0.85 0.1 240 / 0.3), inset 0 0 10px oklch(0.85 0.1 240 / 0.2);
            transform: scale(1.02);
        }.sc-tw .text-gradient{
            background: linear-gradient(180deg, #ffffff 0%, oklch(0.6 0.02 250) 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }.sc-tw .text-refraction{
            color: transparent;
            -webkit-text-stroke: 1px rgba(255, 255, 255, 0.5);
            background: linear-gradient(90deg, rgba(255, 255, 255, 0.1), rgba(255, 255, 255, 0.8), rgba(255, 255, 255, 0.1));
            -webkit-background-clip: text;
            background-size: 200% auto;
            animation: shine 4s linear infinite;
        }

        @keyframes shine {to{
                background-position: 200% center;
            }
        }

        @keyframes atomic-assemble {0%{
                opacity: 0;
                filter: blur(10px);
                transform: translateY(60px);
            }100%{
                opacity: 1;
                filter: blur(0);
                transform: translateY(0);
            }
        }.sc-tw .scroll-driven{
            animation: atomic-assemble linear both;
            animation-timeline: view();
            animation-range: entry 5% cover 25%;
        }.sc-tw ::selection{
            background: var(--accent-photon);
            color: #000;
